  "devices.remote.disclaimerTitle": "遠程連接免責聲明",
  "devices.remote.disclaimerIntro": "遠端連線可讓你遠端操作其他裝置上的 OpenBitFun，也可透過手機、瀏覽器或聊天應用下發任務。啟用前，請閱讀並理解以下說明：",
  "devices.remote.disclaimerKeyRisks": "核心風險",
  "devices.remote.disclaimerFullDetails": "檢視完整的安全、隱私、網路與合規說明",
  "devices.remote.disclaimerItemGeneralRisk": "遠端操作與任務執行可能讀取或修改所選裝置和工作區中的檔案、執行命令。請核對目標與權限；錯誤操作、功能缺陷或連線異常可能造成資料遺失等損失。",
  "devices.remote.disclaimerItemSecurity": "裝置、手機和瀏覽器透過同一 OpenBitFun 帳號連線；聊天應用透過各自的授權與配對流程接入。請只在可信裝置上登入，並僅向可信人員開放控制權限。",
  "devices.remote.disclaimerItemEncryption": "透過官方中繼傳輸的裝置間控制訊息與任務資料採用端對端加密。帳號識別碼、裝置名稱、上線狀態和連線位址等中繼資料不屬於訊息密文；聊天應用通道也不受這層端對端加密保護。",
  "devices.remote.disclaimerItemOpenSource": "OpenBitFun 遠程連接的加密實現完全開源，你可以自行審計源碼以驗證安全性。",
  "devices.remote.disclaimerItemPrivacy": "任務內容、附件和執行結果可能包含敏感資訊，並顯示在連線端或聊天記錄中。執行裝置的日誌、瀏覽器以及接入的第三方服務也可能保留相關資料，請按需控制傳送內容與存取權限。",
  "devices.remote.disclaimerItemDataUsage": "OpenBitFun 不會將你的遠端連線業務內容用於訓練或商業化使用；你選擇接入的模型服務和聊天平台（如飛書、Telegram、微信）可能按各自條款處理資料。",
  "devices.remote.disclaimerItemCredentials": "請妥善保護 OpenBitFun 帳號、各裝置與瀏覽器的登入憑證，以及聊天應用的 Token、App Secret 等接入憑證。憑證外洩或裝置失竊可能導致他人下發任務或存取資料。",
  "devices.remote.disclaimerItemQrCode": "連線 QR 碼和連結包含中繼位址與目標裝置識別碼，開啟後仍需使用同一 OpenBitFun 帳號登入。請避免向無關人員傳播，並在登入與連線前核對位址與目標裝置。",
  "devices.remote.disclaimerItemRelay": "官方中繼用於連線和轉發訊息，不代替執行裝置執行任務。執行裝置需要保持上線；關閉連線視窗或取消邀請不會自動中斷已建立的帳號連線，請在連線管理中主動中斷。",
  "devices.remote.disclaimerItemNetwork": "直連需要裝置之間能夠互相存取；路由器隔離、防火牆和代理設定可能阻止連線。官方中繼還依賴網際網路與服務可用性，網路變化可能造成中斷或延遲。",
  "devices.remote.disclaimerItemBot": "聊天應用配對碼用於建立與執行裝置的連線，配對後可透過聊天應用下發任務。請勿向無關人員洩露配對碼，並注意聊天帳號、群組成員及平台權限設定。",
  "devices.remote.disclaimerItemBotPersistence": "聊天應用的接入憑證和配對資訊會儲存在執行裝置上，以便重新啟動後恢復連線。請保護該裝置及其設定檔；無需繼續使用時，請主動中斷連線。",
  "devices.remote.disclaimerItemMobileBrowser": "手機或瀏覽器可能保留登入憑證、頁面快取及任務內容，截圖、剪貼簿和擴充程式也可能暴露資訊。請勿在共用或不可信裝置上保留登入狀態。",
  "devices.remote.disclaimerItemCompliance": "部分國家或地區對加密通信、隧道服務、跨境資料傳輸等有法規限制，請自行評估當地法律合規性；其他監管政策變化也可能影響功能可用性與合規義務。",
  "devices.remote.disclaimerItemLiability": "使用遠程連接功能過程中產生的風險、損失、糾紛或其他不利後果（包括但不限於資料洩露、連接中斷、賬號異常、服務不可用等）由你自行承擔；OpenBitFun 不對由此造成的問題負責。",
  "devices.remote.disclaimerReview": "查看免責聲明",
